59: 
60: #define REPEAT 5
61: #define min(a, b) (((a) < (b)) ? (a) : (b))
62: 
63: #define HX(a, b) \
64: 	do { \
65: 		if ((a)) \
66: 			HD(errno); \
67: 		else \
68: 			HD(b); \
69: 	} while (0)
70: 
71: #define HR(x, l) (SHA512_Update(&ctx, (uint8_t *)(x), (l)))
72: #define HD(x)	 (SHA512_Update(&ctx, (uint8_t *)&(x), sizeof (x)))
73: #define HF(x)    (SHA512_Update(&ctx, (uint8_t *)&(x), sizeof (void*)))
74: 
75: int	getentropy(void *buf, size_t len);
76: 
77: static int gotdata(char *buf, size_t len);
78: #if defined(SYS_getrandom) && defined(GRND_NONBLOCK)
79: static int getentropy_getrandom(void *buf, size_t len);
80: #endif
81: static int getentropy_urandom(void *buf, size_t len);
82: #ifdef SYS__sysctl
83: static int getentropy_sysctl(void *buf, size_t len);
84: #endif
85: static int getentropy_fallback(void *buf, size_t len);
86: static int getentropy_phdr(struct dl_phdr_info *info, size_t size, void *data);
87: 
88: int
89: getentropy(void *buf, size_t len)
90: {
91: 	int ret = -1;
92: 
93: 	if (len > 256) {
94: 		errno = EIO;
95: 		return (-1);
96: 	}
97: 
98: #if defined(SYS_getrandom) && defined(GRND_NONBLOCK)
99: 	/*
100: 	 * Try descriptor-less getrandom(), in non-blocking mode.
101: 	 *
102: 	 * The design of Linux getrandom is broken.  It has an
103: 	 * uninitialized phase coupled with blocking behaviour, which
104: 	 * is unacceptable from within a library at boot time without
105: 	 * possible recovery. See http://bugs.python.org/issue26839#msg267745
106: 	 */
107: 	ret = getentropy_getrandom(buf, len);
108: 	if (ret != -1)
109: 		return (ret);
110: #endif
111: 
112: 	/*
113: 	 * Try to get entropy with /dev/urandom
114: 	 *
115: 	 * This can fail if the process is inside a chroot or if file
116: 	 * descriptors are exhausted.
117: 	 */
118: 	ret = getentropy_urandom(buf, len);
119: 	if (ret != -1)
120: 		return (ret);
121: 
122: #ifdef SYS__sysctl
123: 	/*
124: 	 * Try to use sysctl CTL_KERN, KERN_RANDOM, RANDOM_UUID.
125: 	 * sysctl is a failsafe API, so it guarantees a result.  This
126: 	 * should work inside a chroot, or when file descriptors are
127: 	 * exhausted.
128: 	 *
129: 	 * However this can fail if the Linux kernel removes support
130: 	 * for sysctl.  Starting in 2007, there have been efforts to
131: 	 * deprecate the sysctl API/ABI, and push callers towards use
132: 	 * of the chroot-unavailable fd-using /proc mechanism --
133: 	 * essentially the same problems as /dev/urandom.
134: 	 *
135: 	 * Numerous setbacks have been encountered in their deprecation
136: 	 * schedule, so as of June 2014 the kernel ABI still exists on
137: 	 * most Linux architectures. The sysctl() stub in libc is missing
138: 	 * on some systems.  There are also reports that some kernels
139: 	 * spew messages to the console.
140: 	 */
141: 	ret = getentropy_sysctl(buf, len);
142: 	if (ret != -1)
143: 		return (ret);
144: #endif /* SYS__sysctl */
145: 
146: 	/*
147: 	 * Entropy collection via /dev/urandom and sysctl have failed.
148: 	 *
149: 	 * No other API exists for collecting entropy.  See the large
150: 	 * comment block above.
151: 	 *
152: 	 * We have very few options:
153: 	 *     - Even syslog_r is unsafe to call at this low level, so
154: 	 *	 there is no way to alert the user or program.
155: 	 *     - Cannot call abort() because some systems have unsafe
156: 	 *	 corefiles.
157: 	 *     - Could raise(SIGKILL) resulting in silent program termination.
158: 	 *     - Return EIO, to hint that arc4random's stir function
159: 	 *       should raise(SIGKILL)
160: 	 *     - Do the best under the circumstances....
161: 	 *
162: 	 * This code path exists to bring light to the issue that Linux
163: 	 * still does not provide a failsafe API for entropy collection.
164: 	 *
165: 	 * We hope this demonstrates that Linux should either retain their
166: 	 * sysctl ABI, or consider providing a new failsafe API which
167: 	 * works in a chroot or when file descriptors are exhausted.
168: 	 */
169: #undef FAIL_INSTEAD_OF_TRYING_FALLBACK
170: #ifdef FAIL_INSTEAD_OF_TRYING_FALLBACK
171: 	raise(SIGKILL);
172: #endif
173: 	ret = getentropy_fallback(buf, len);
174: 	if (ret != -1)
175: 		return (ret);
176: 
177: 	errno = EIO;
178: 	return (ret);
179: }
