181: /*
182:  * Basic sanity checking; wish we could do better.
183:  */
184: static int
185: gotdata(char *buf, size_t len)
186: {
187: 	char	any_set = 0;
188: 	size_t	i;
189: 
190: 	for (i = 0; i < len; ++i)
191: 		any_set |= buf[i];
192: 	if (any_set == 0)
193: 		return (-1);
194: 	return (0);
195: }
