199: getentropy_getrandom(void *buf, size_t len)
200: {
201: 	int pre_errno = errno;
202: 	int ret;
203: 	if (len > 256)
204: 		return (-1);
205: 	do {
206: 		ret = syscall(SYS_getrandom, buf, len, GRND_NONBLOCK);
207: 	} while (ret == -1 && errno == EINTR);
208: 
209: 	if (ret != (int)len)
210: 		return (-1);
211: 	errno = pre_errno;
212: 	return (0);
213: }
