276: getentropy_sysctl(void *buf, size_t len)
277: {
278: 	static int mib[] = { CTL_KERN, KERN_RANDOM, RANDOM_UUID };
279: 	size_t i;
280: 	int save_errno = errno;
281: 
282: 	for (i = 0; i < len; ) {
283: 		size_t chunk = min(len - i, 16);
284: 
285: 		/* SYS__sysctl because some systems already removed sysctl() */
286: 		struct __sysctl_args args = {
287: 			.name = mib,
288: 			.nlen = 3,
289: 			.oldval = (char *)buf + i,
290: 			.oldlenp = &chunk,
291: 		};
292: 		if (syscall(SYS__sysctl, &args) != 0)
293: 			goto sysctlfailed;
294: 		i += chunk;
295: 	}
296: 	if (gotdata(buf, len) == 0) {
297: 		errno = save_errno;
298: 		return (0);			/* satisfied */
299: 	}
300: sysctlfailed:
301: 	errno = EIO;
302: 	return (-1);
303: }
304: #endif /* SYS__sysctl */
