306: static const int cl[] = {
307: 	CLOCK_REALTIME,
308: #ifdef CLOCK_MONOTONIC
309: 	CLOCK_MONOTONIC,
310: #endif
311: #ifdef CLOCK_MONOTONIC_RAW
312: 	CLOCK_MONOTONIC_RAW,
313: #endif
314: #ifdef CLOCK_TAI
315: 	CLOCK_TAI,
316: #endif
317: #ifdef CLOCK_VIRTUAL
318: 	CLOCK_VIRTUAL,
319: #endif
320: #ifdef CLOCK_UPTIME
321: 	CLOCK_UPTIME,
322: #endif
323: #ifdef CLOCK_PROCESS_CPUTIME_ID
