340: static int
341: getentropy_fallback(void *buf, size_t len)
342: {
343: 	uint8_t results[SHA512_DIGEST_LENGTH];
344: 	int save_errno = errno, e, pgs = getpagesize(), faster = 0, repeat;
345: 	static int cnt;
346: 	struct timespec ts;
347: 	struct timeval tv;
348: 	struct rusage ru;
349: 	sigset_t sigset;
350: 	struct stat st;
351: 	SHA512_CTX ctx;
352: 	static pid_t lastpid;
353: 	pid_t pid;
354: 	size_t i, ii, m;
355: 	char *p;
356: 
357: 	pid = getpid();
358: 	if (lastpid == pid) {
359: 		faster = 1;
360: 		repeat = 2;
361: 	} else {
362: 		faster = 0;
363: 		lastpid = pid;
364: 		repeat = REPEAT;
365: 	}
366: 	for (i = 0; i < len; ) {
367: 		int j;
368: 		SHA512_Init(&ctx);
369: 		for (j = 0; j < repeat; j++) {
370: 			HX((e = gettimeofday(&tv, NULL)) == -1, tv);
371: 			if (e != -1) {
372: 				cnt += (int)tv.tv_sec;
373: 				cnt += (int)tv.tv_usec;
374: 			}
375: 
376: 			dl_iterate_phdr(getentropy_phdr, &ctx);
377: 
378: 			for (ii = 0; ii < sizeof(cl)/sizeof(cl[0]); ii++)
379: 				HX(clock_gettime(cl[ii], &ts) == -1, ts);
380: 
381: 			HX((pid = getpid()) == -1, pid);
382: 			HX((pid = getsid(pid)) == -1, pid);
383: 			HX((pid = getppid()) == -1, pid);
384: 			HX((pid = getpgid(0)) == -1, pid);
385: 			HX((e = getpriority(0, 0)) == -1, e);
386: 
387: 			if (!faster) {
388: 				ts.tv_sec = 0;
389: 				ts.tv_nsec = 1;
390: 				(void) nanosleep(&ts, NULL);
391: 			}
392: 
393: 			HX(sigpending(&sigset) == -1, sigset);
394: 			HX(sigprocmask(SIG_BLOCK, NULL, &sigset) == -1,
395: 			    sigset);
396: 
397: 			HF(getentropy);	/* an addr in this library */
398: 			HF(printf);		/* an addr in libc */
399: 			p = (char *)&p;
400: 			HD(p);		/* an addr on stack */
401: 			p = (char *)&errno;
402: 			HD(p);		/* the addr of errno */
403: 
404: 			if (i == 0) {
405: 				struct sockaddr_storage ss;
406: 				struct statvfs stvfs;
407: 				struct termios tios;
408: 				struct statfs stfs;
409: 				socklen_t ssl;
410: 				off_t off;
411: 
412: 				/*
413: 				 * Prime-sized mappings encourage fragmentation;
414: 				 * thus exposing some address entropy.
415: 				 */
416: 				struct mm {
417: 					size_t	npg;
418: 					void	*p;
419: 				} mm[] =	 {
420: 					{ 17, MAP_FAILED }, { 3, MAP_FAILED },
421: 					{ 11, MAP_FAILED }, { 2, MAP_FAILED },
422: 					{ 5, MAP_FAILED }, { 3, MAP_FAILED },
423: 					{ 7, MAP_FAILED }, { 1, MAP_FAILED },
424: 					{ 57, MAP_FAILED }, { 3, MAP_FAILED },
425: 					{ 131, MAP_FAILED }, { 1, MAP_FAILED },
426: 				};
427: 
428: 				for (m = 0; m < sizeof mm/sizeof(mm[0]); m++) {
429: 					HX(mm[m].p = mmap(NULL,
430: 					    mm[m].npg * pgs,
431: 					    PROT_READ|PROT_WRITE,
432: 					    MAP_PRIVATE|MAP_ANON, -1,
433: 					    (off_t)0), mm[m].p);
434: 					if (mm[m].p != MAP_FAILED) {
435: 						size_t mo;
436: 
437: 						/* Touch some memory... */
438: 						p = mm[m].p;
439: 						mo = cnt %
440: 						    (mm[m].npg * pgs - 1);
441: 						p[mo] = 1;
442: 						cnt += (int)((long)(mm[m].p)
443: 						    / pgs);
444: 					}
445: 
446: 					/* Check cnts and times... */
447: 					for (ii = 0; ii < sizeof(cl)/sizeof(cl[0]);
448: 					    ii++) {
449: 						HX((e = clock_gettime(cl[ii],
450: 						    &ts)) == -1, ts);
451: 						if (e != -1)
452: 							cnt += (int)ts.tv_nsec;
453: 					}
454: 
455: 					HX((e = getrusage(RUSAGE_SELF,
456: 					    &ru)) == -1, ru);
457: 					if (e != -1) {
458: 						cnt += (int)ru.ru_utime.tv_sec;
459: 						cnt += (int)ru.ru_utime.tv_usec;
460: 					}
461: 				}
462: 
463: 				for (m = 0; m < sizeof mm/sizeof(mm[0]); m++) {
464: 					if (mm[m].p != MAP_FAILED)
465: 						munmap(mm[m].p, mm[m].npg * pgs);
466: 					mm[m].p = MAP_FAILED;
467: 				}
468: 
469: 				HX(stat(".", &st) == -1, st);
470: 				HX(statvfs(".", &stvfs) == -1, stvfs);
471: 				HX(statfs(".", &stfs) == -1, stfs);
472: 
473: 				HX(stat("/", &st) == -1, st);
474: 				HX(statvfs("/", &stvfs) == -1, stvfs);
475: 				HX(statfs("/", &stfs) == -1, stfs);
476: 
477: 				HX((e = fstat(0, &st)) == -1, st);
478: 				if (e == -1) {
479: 					if (S_ISREG(st.st_mode) ||
480: 					    S_ISFIFO(st.st_mode) ||
481: 					    S_ISSOCK(st.st_mode)) {
482: 						HX(fstatvfs(0, &stvfs) == -1,
483: 						    stvfs);
484: 						HX(fstatfs(0, &stfs) == -1,
485: 						    stfs);
486: 						HX((off = lseek(0, (off_t)0,
487: 						    SEEK_CUR)) < 0, off);
488: 					}
489: 					if (S_ISCHR(st.st_mode)) {
490: 						HX(tcgetattr(0, &tios) == -1,
491: 						    tios);
492: 					} else if (S_ISSOCK(st.st_mode)) {
493: 						memset(&ss, 0, sizeof ss);
494: 						ssl = sizeof(ss);
495: 						HX(getpeername(0,
496: 						    (void *)&ss, &ssl) == -1,
497: 						    ss);
498: 					}
499: 				}
500: 
501: 				HX((e = getrusage(RUSAGE_CHILDREN,
502: 				    &ru)) == -1, ru);
503: 				if (e != -1) {
504: 					cnt += (int)ru.ru_utime.tv_sec;
505: 					cnt += (int)ru.ru_utime.tv_usec;
506: 				}
507: 			} else {
508: 				/* Subsequent hashes absorb previous result */
509: 				HD(results);
510: 			}
511: 
512: 			HX((e = gettimeofday(&tv, NULL)) == -1, tv);
513: 			if (e != -1) {
514: 				cnt += (int)tv.tv_sec;
515: 				cnt += (int)tv.tv_usec;
516: 			}
517: 
518: 			HD(cnt);
519: 		}
520: #ifdef HAVE_GETAUXVAL
521: #ifdef AT_RANDOM
522: 		/* Not as random as you think but we take what we are given */
523: 		p = (char *) ((intptr_t) getauxval(AT_RANDOM));
524: 		if (p)
525: 			HR(p, 16);
526: #endif
527: #ifdef AT_SYSINFO_EHDR
528: 		p = (char *) ((intptr_t) getauxval(AT_SYSINFO_EHDR));
529: 		if (p)
530: 			HR(p, pgs);
531: #endif
532: #ifdef AT_BASE
533: 		p = (char *) ((intptr_t) getauxval(AT_BASE));
534: 		if (p)
535: 			HD(p);
536: #endif
537: #endif
538: 
539: 		SHA512_Final(results, &ctx);
540: 		memcpy((char *)buf + i, results, min(sizeof(results), len - i));
541: 		i += min(sizeof(results), len - i);
542: 	}
543: 	explicit_bzero(&ctx, sizeof ctx);
544: 	explicit_bzero(results, sizeof results);
545: 	if (gotdata(buf, len) == 0) {
546: 		errno = save_errno;
547: 		return (0);		/* satisfied */
548: 	}
549: 	errno = EIO;
550: 	return (-1);
551: }

